code='''def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    boxes = []
    for color in range(1, 10):
        cells = [(r,c) for r in range(h) for c in range(w) if g[r][c] == color]
        if not cells:
            continue
        r0, r1 = min(r for r,c in cells), max(r for r,c in cells)
        c0, c1 = min(c for r,c in cells), max(c for r,c in cells)
        # Frames have a complete rectangular perimeter in their color.
        if all(g[r0][c] == color and g[r1][c] == color for c in range(c0,c1+1)) and all(g[r][c0] == color and g[r][c1] == color for r in range(r0,r1+1)):
            if r1-r0 >= 2 and c1-c0 >= 2:
                box = (color,r0,r1,c0,c1)
                interior = [[g[r][c] for c in range(c0+1,c1)] for r in range(r0+1,r1)]
                boxes.append((box, interior))
    sources = [(b,p) for b,p in boxes if any(v != 0 for row in p for v in row)]
    if not sources:
        return g
    # The unique patterned frame supplies its binary motif to blank frames of identical interior size.
    (sb, pattern) = max(sources, key=lambda bp: sum(v != 0 for row in bp[1] for v in row))
    sh, sw = len(pattern), len(pattern[0])
    for (color,r0,r1,c0,c1), interior in boxes:
        if color == sb[0] or len(interior) != sh or len(interior[0]) != sw:
            continue
        if any(v != 0 for row in interior for v in row):
            continue
        for i in range(sh):
            for j in range(sw):
                if pattern[i][j] != 0:
                    g[r0+1+i][c0+1+j] = color
    return g
